{
  "name": "通用USB实验设备",
  "name_en": "Generic USB Laboratory Device",
  "manufacturer": "",
  "description": "一种通过USB连接到主机的通用实验设备或仪器接口。该类设备可用于实验室中的数据采集、控制、配置与数据传输，具体功能取决于所连接的实际USB仪器。",
  "description_en": "A generic laboratory device or instrument interface connected to a host via USB. Such devices are used in labs for data acquisition, control, configuration, and data transfer, with the exact function depending on the specific USB instrument attached.",
  "tag_hints": [
    "USB communication",
    "laboratory instrument interface",
    "device configuration",
    "bulk interrupt isochronous transfer",
    "control transfer",
    "USB endpoint management"
  ],
  "actions": [
    {
      "action_name": "auto-enumerate_devices",
      "description": "枚举主机可访问的已连接USB设备。",
      "description_en": "Enumerate connected USB devices accessible to the host."
    },
    {
      "action_name": "auto-open_device",
      "description": "打开与USB设备的连接。",
      "description_en": "Open a connection to the USB device."
    },
    {
      "action_name": "auto-close_device",
      "description": "关闭与USB设备的连接。",
      "description_en": "Close the connection to the USB device."
    },
    {
      "action_name": "auto-set_configuration",
      "description": "设置设备的USB配置。",
      "description_en": "Set the device USB configuration."
    },
    {
      "action_name": "auto-set_interface_altsetting",
      "description": "为设备接口选择备用设置。",
      "description_en": "Select an alternate setting for a device interface."
    },
    {
      "action_name": "auto-claim_interface",
      "description": "声明并占用设备接口以进行通信。",
      "description_en": "Claim a device interface for communication."
    },
    {
      "action_name": "auto-release_interface",
      "description": "释放先前占用的设备接口。",
      "description_en": "Release a previously claimed device interface."
    },
    {
      "action_name": "auto-bulk_write",
      "description": "通过批量传输向设备写入数据。",
      "description_en": "Write data to the device using a bulk transfer."
    },
    {
      "action_name": "auto-bulk_read",
      "description": "通过批量传输从设备读取数据。",
      "description_en": "Read data from the device using a bulk transfer."
    },
    {
      "action_name": "auto-intr_write",
      "description": "通过中断传输向设备写入数据。",
      "description_en": "Write data to the device using an interrupt transfer."
    },
    {
      "action_name": "auto-intr_read",
      "description": "通过中断传输从设备读取数据。",
      "description_en": "Read data from the device using an interrupt transfer."
    },
    {
      "action_name": "auto-iso_write",
      "description": "通过等时传输向设备写入数据。",
      "description_en": "Write data to the device using an isochronous transfer."
    },
    {
      "action_name": "auto-iso_read",
      "description": "通过等时传输从设备读取数据。",
      "description_en": "Read data from the device using an isochronous transfer."
    },
    {
      "action_name": "auto-ctrl_transfer",
      "description": "执行设备控制传输以发送命令或读取控制信息。",
      "description_en": "Perform a control transfer to send commands or read control information."
    },
    {
      "action_name": "auto-clear_halt",
      "description": "清除设备端点的暂停或错误状态。",
      "description_en": "Clear a halt or error condition on a device endpoint."
    },
    {
      "action_name": "auto-reset_device",
      "description": "复位USB设备。",
      "description_en": "Reset the USB device."
    },
    {
      "action_name": "auto-is_kernel_driver_active",
      "description": "检查设备接口上是否有内核驱动正在占用。",
      "description_en": "Check whether a kernel driver is attached to the device interface."
    },
    {
      "action_name": "auto-detach_kernel_driver",
      "description": "将设备接口与已附加的内核驱动分离。",
      "description_en": "Detach an attached kernel driver from the device interface."
    }
  ]
}

